solution.code:
function welcome(name: string, opts: { upper: boolean } = { upper: false }): string {
  return opts.upper ? name.toUpperCase() : name;
}

console.log(welcome('ada'));
console.log(welcome('ada', { upper: true }));

function once<A extends any[], R>(fn: (...args: A) => R): (...args: A) => R {
  let called = false;
  let result: R;
  return (...args: A): R => {
    if (!called) {
      called = true;
      result = fn(...args);
    }
    return result;
  };
}

const init = once((name: string) => {
  console.log('init', name);
  return name.length;
});
console.log(init('ada'));
console.log(init('linus'));
